-- 借阅管理

CREATE TABLE `scc_npm_borrow`
(
    `BORROW_ID`              bigint(20)  NOT NULL COMMENT '主键id',
    `BORROW_NUM`             varchar(30)  NOT NULL COMMENT '借阅申请单号',
    `STATUS`          varchar(50) NOT NULL COMMENT '状态',
    `BIDING_ID`              bigint(20)           DEFAULT NULL COMMENT '招标项目ID',
    `BIDING_NUM`             varchar(30)          DEFAULT NULL COMMENT '招标项目编码',
    `BIDING_NAME`            varchar(240)         DEFAULT NULL COMMENT '招标项目名称',
    `DEPARTMENT_ID`          bigint(20)           DEFAULT NULL COMMENT '部门id',
    `DEPARTMENT_CODE`        varchar(50)          DEFAULT NULL COMMENT '部门编码',
    `DEPARTMENT_NAME`        varchar(50)          DEFAULT NULL COMMENT '部门名称',
    `APPLY_USER_CODE`        varchar(50)          DEFAULT NULL COMMENT '申请人工号',
    `APPLY_USER_NAME`        varchar(50)          DEFAULT NULL COMMENT '申请人名称',
    `APPLY_CONTACTS`         varchar(50)          DEFAULT NULL COMMENT '申请人联系方式',
    `BORROW_TYPE`            varchar(50)          DEFAULT NULL COMMENT '借阅资料类型',
    `BORROW_CAUSE`           varchar(1000)          DEFAULT NULL COMMENT '申请使用原因',
    `USE_TYPE`               varchar(50)          DEFAULT NULL COMMENT '使用方式',
    `PRICE_FLAG`             varchar(10)          DEFAULT NULL COMMENT '是否涉及报价，Y/N',
    `CREATED_ID`             bigint(20)  NOT NULL COMMENT '创建人ID',
    `CREATED_BY`             varchar(50) NOT NULL COMMENT '创建人',
    `CREATION_DATE`          datetime    NOT NULL COMMENT '创建时间',
    `CREATED_BY_IP`          varchar(150)         DEFAULT NULL COMMENT '创建人IP',
    `CREATED_FULL_NAME`      varchar(100)         DEFAULT NULL COMMENT '创建人姓名',
    `LAST_UPDATED_ID`        bigint(20)           DEFAULT NULL COMMENT '最后更新人ID',
    `LAST_UPDATED_BY`        varchar(50)          DEFAULT NULL COMMENT '更新人',
    `LAST_UPDATE_DATE`       datetime             DEFAULT NULL COMMENT '最后更新时间',
    `LAST_UPDATED_BY_IP`     varchar(150)         DEFAULT NULL COMMENT '最后更新人IP',
    `LAST_UPDATED_FULL_NAME` varchar(100)         DEFAULT NULL COMMENT '最后更新人姓名',
    `TENANT_ID`              varchar(30)          DEFAULT NULL COMMENT '租户ID',
    `VERSION`                bigint(20)  NOT NULL DEFAULT 0 COMMENT '版本号',
    PRIMARY KEY (`BORROW_ID`) USING BTREE,
    KEY `scc_npm_borrow_BIDING_NUM_IDX` (`BIDING_NUM`) USING BTREE
) ENGINE = InnoDB COMMENT ='借阅申请';

-- 借阅申请附件

CREATE TABLE `scc_npm_borrow_attach`
(
    `BORROW_ATTACH_ID`      bigint(20)  NOT NULL COMMENT '主键id',
    `BORROW_ID`             bigint(20)  NOT NULL COMMENT '考察申请id',
    `ATTACH_ID`              bigint(20)           DEFAULT NULL COMMENT '附件ID',
    `ATTACH_NAME`            varchar(50)          DEFAULT NULL COMMENT '附件名称',
    `ATTACH_PATH`              VARCHAR(200)           DEFAULT NULL COMMENT '附件路径',
    `CREATED_ID`             bigint(20)  NOT NULL COMMENT '创建人ID',
    `CREATED_BY`             varchar(50) NOT NULL COMMENT '创建人',
    `CREATION_DATE`          datetime    NOT NULL COMMENT '创建时间',
    `CREATED_BY_IP`          varchar(150)         DEFAULT NULL COMMENT '创建人IP',
    `CREATED_FULL_NAME`      varchar(100)         DEFAULT NULL COMMENT '创建人姓名',
    `LAST_UPDATED_ID`        bigint(20)           DEFAULT NULL COMMENT '最后更新人ID',
    `LAST_UPDATED_BY`        varchar(50)          DEFAULT NULL COMMENT '更新人',
    `LAST_UPDATE_DATE`       datetime             DEFAULT NULL COMMENT '最后更新时间',
    `LAST_UPDATED_BY_IP`     varchar(150)         DEFAULT NULL COMMENT '最后更新人IP',
    `LAST_UPDATED_FULL_NAME` varchar(100)         DEFAULT NULL COMMENT '最后更新人姓名',
    `TENANT_ID`              varchar(30)          DEFAULT NULL COMMENT '租户ID',
    `VERSION`                bigint(20)  NOT NULL DEFAULT 0 COMMENT '版本号',
    PRIMARY KEY (`BORROW_ATTACH_ID`) USING BTREE,
    KEY `scc_npm_borrow_attach_BORROW_ID_IDX` (`BORROW_ID`) USING BTREE
) ENGINE = InnoDB COMMENT ='借阅附件';

-- 考察申请

CREATE TABLE `scc_npm_inspect`
(
    `INSPECT_ID`               bigint(20)  NOT NULL COMMENT '主键id',
    `INSPECT_NUM`              varchar(30)  NOT NULL COMMENT '考察申请单号',
    `REPORT_NUM`              varchar(30)  NOT NULL COMMENT '考察报告单号',
    `INSPECT_STATUS`           varchar(50) NOT NULL COMMENT '状态',
    `BIDING_ID`                bigint(20)           DEFAULT NULL COMMENT '招标项目ID',
    `BIDING_NUM`               varchar(30)          DEFAULT NULL COMMENT '招标项目编码',
    `BIDING_NAME`              varchar(240)         DEFAULT NULL COMMENT '招标项目名称',
    `BIDING_head`              varchar(240)         DEFAULT NULL COMMENT '招标项目负责人',
    `BIDING_DEPARTMENT_FLAG`   varchar(10)          DEFAULT NULL COMMENT '招标部是否参加，Y/N',
    `ORG_ID`                   bigint(20)           DEFAULT NULL COMMENT '业务实体ID',
    `ORG_CODE`                 varchar(50)          DEFAULT NULL COMMENT '业务实体编码',
    `ORG_NAME`                 varchar(50)          DEFAULT NULL COMMENT '业务实体名称',
    `DEPARTMENT_ID`            bigint(20)           DEFAULT NULL COMMENT '部门id',
    `DEPARTMENT_CODE`          varchar(50)          DEFAULT NULL COMMENT '部门编码',
    `DEPARTMENT_NAME`          varchar(50)          DEFAULT NULL COMMENT '部门名称',
    `COME_TYPE`                varchar(50)          DEFAULT NULL COMMENT '出行方式',
    `COMMENT`                  varchar(500)         DEFAULT NULL COMMENT '备注（拟参加人员）',
    `COMPREHENSIVE_EVALUATION` varchar(2000)         DEFAULT NULL COMMENT '综合评估意见',
    `LEADER_EVALUATION`        varchar(2000)         DEFAULT NULL COMMENT '组长评估意见',
    `CREATED_ID`               bigint(20)  NOT NULL COMMENT '创建人ID',
    `CREATED_BY`               varchar(50) NOT NULL COMMENT '创建人',
    `CREATION_DATE`            datetime    NOT NULL COMMENT '创建时间',
    `CREATED_BY_IP`            varchar(150)         DEFAULT NULL COMMENT '创建人IP',
    `CREATED_FULL_NAME`        varchar(100)         DEFAULT NULL COMMENT '创建人姓名',
    `LAST_UPDATED_ID`          bigint(20)           DEFAULT NULL COMMENT '最后更新人ID',
    `LAST_UPDATED_BY`          varchar(50)          DEFAULT NULL COMMENT '更新人',
    `LAST_UPDATE_DATE`         datetime             DEFAULT NULL COMMENT '最后更新时间',
    `LAST_UPDATED_BY_IP`       varchar(150)         DEFAULT NULL COMMENT '最后更新人IP',
    `LAST_UPDATED_FULL_NAME`   varchar(100)         DEFAULT NULL COMMENT '最后更新人姓名',
    `TENANT_ID`                varchar(30)          DEFAULT NULL COMMENT '租户ID',
    `VERSION`                  bigint(20)  NOT NULL DEFAULT 0 COMMENT '版本号',
    PRIMARY KEY (`INSPECT_ID`) USING BTREE,
    KEY `scc_npm_inspect_BIDING_NUM_IDX` (`BIDING_NUM`) USING BTREE,
    KEY `scc_npm_inspect_INSPECT_NUM_IDX` (`INSPECT_NUM`) USING BTREE
) ENGINE = InnoDB COMMENT ='考察申请';


-- 考察申请附件

CREATE TABLE `scc_npm_inspect_attach`
(
    `INSPECT_ATTACH_ID`      bigint(20)  NOT NULL COMMENT '主键id',
