-- 考察申请单位

CREATE TABLE `scc_npm_inspect_vendor`
(
    `INSPECT_VENDOR_ID`      bigint(20)  NOT NULL COMMENT '主键id',
    `INSPECT_ID`             bigint(20)  NOT NULL COMMENT '考察申请id',
    `VENDOR_ID`              bigint(20)           DEFAULT NULL COMMENT '供应商ID',
